// Normalizes input from Schedule, Webhook, Telegram Message, or Telegram Callback Query
// Persistent Channel Memory & Multi-Video Engine Integration using n8n getWorkflowStaticData
const item = $input.first().json;
const body = item.body || item;

// 1. Initialize or Load Persistent Channel Memory
const staticData = (typeof  === 'function') ? ('global') : (typeof getWorkflowStaticData === 'function' ? getWorkflowStaticData('global') : {});

const defaultProfile = {
  niche: "AI Automation, Multi-Agent Swarms & Future Tech Engineering",
  target_audience: "Software Engineers, Tech Founders, Automation Builders & AI Enthusiasts",
  tone_of_voice: "Energetic, visionary, high-authority, actionable, no fluff",
  language: "Turkish (with modern global tech terms)",
  visual_aesthetic: "Futuristic 9:16 vertical, dark cybernetic mode, glowing neon, high-contrast kinetic typography",
  custom_instructions: "Focus on practical software agent architectures, 2026 tech trends, autonomous coding, and workflow automation. Every hook must trigger immediate curiosity or challenge outdated practices in the first 3 seconds.",
  last_updated: new Date().toISOString()
};

const defaultLibrary = [
  {
    category: "swarms_agents",
    keywords: ["swarm", "agent", "autonomous", "bot", "orchestration", "workflow", "multi"],
    url: "https://n8n-advanced.codewaft.com/media/cyber_agent.mp4"
  },
  {
    category: "coding_devtools",
    keywords: ["code", "developer", "software", "api", "git", "python", "syntax", "debug", "terminal"],
    url: "https://n8n-advanced.codewaft.com/media/matrix_code.mp4"
  },
  {
    category: "neural_reasoning",
    keywords: ["neural", "reasoning", "llm", "deepseek", "gpt", "model", "intelligence", "brain", "prompt"],
    url: "https://n8n-advanced.codewaft.com/media/neural_core.mp4"
  },
  {
    category: "robotics_hardware",
    keywords: ["robot", "hardware", "quantum", "chip", "future", "vision", "device"],
    url: "https://n8n-advanced.codewaft.com/media/reel_sample.mp4"
  }
];

if (!staticData.channel_profile) {
  staticData.channel_profile = defaultProfile;
}
if (!staticData.recent_topics) {
  staticData.recent_topics = [
    "Why Multi-Agent AI Swarms Replace Prompts in 2026",
    "Autonomous AI Swarms in 2026",
    "AI Code Generation vs Multi-Agent Orchestration"
  ];
}
if (!staticData.video_library) {
  staticData.video_library = defaultLibrary;
}

// 2. Detect Callback Query (Inline Button Click)
if (body.callback_query) {
  const cb = body.callback_query;
  const data = cb.data || '';
  const parts = data.split(':');
  const action = parts[1] || 'approve';
  const jobId = parts[2] || ('job_' + Date.now());
  const chatId = String(cb.message?.chat?.id || cb.from?.id || '1519369571');
  const messageText = cb.message?.text || '';

  // Extract video link from entities or regex
  let videoUrl = 'https://n8n-advanced.codewaft.com/media/cyber_agent.mp4';
  if (cb.message?.entities && Array.isArray(cb.message.entities)) {
    const linkEntity = cb.message.entities.find(e => e.type === 'text_link' && e.url);
    if (linkEntity && linkEntity.url) {
      videoUrl = linkEntity.url;
    }
  }

  // Extract topic and hook from messageText
  let topic = 'AI Multi-Agent Swarms in 2026';
  const topicMatch = messageText.match(/Topic:\s*([^\n]+)/i);
  if (topicMatch) topic = topicMatch[1].trim();

  let hook = 'Stop writing prompts. Build swarms instead.';
  const hookMatch = messageText.match(/Hook:\s*"?([^"\n]+)"?/i);
  if (hookMatch) hook = hookMatch[1].trim();

  const caption = `${hook}\n\n${topic}\n\n🚀 Produced by AI Reel Factory #AI2026 #Automation #Reels #Shorts`;

  return [{
    json: {
      actionType: 'callback',
      callbackId: cb.id,
      action,
      jobId,
      chatId,
      topic,
      hook,
      videoUrl,
      caption,
      isInfo: false,
      isStart: false,
      isCallback: true
    }
  }];
}

// 3. Normal Message / Webhook / Schedule Trigger
const msg = item.message || body.message || body;
const text = (msg.text || '').trim();
const chatId = String(msg.chat?.id || body.chat_id || item.chat_id || '1519369571');

// --- Command: /start ---
if (text === '/start') {
  const welcomeText = `👋 <b>Merhaba! Akıllı Asenkron AI Reel Fabrikasına Hoş Geldiniz!</b>\n━━━━━━━━━━━━━━━━━━━━━━\n🎬 Bu fabrika sadece tek tip video üretmez; kanalınızın nişine, hedef kitlesine ve ses tonuna göre tamamen dinamik 9:16 dikey videolar hazırlar!\n\n⚡ <b>Kullanabileceğiniz Komutlar:</b>\n• <code>/reel &lt;konu&gt;</code> ➔ Belirttiğiniz konuda anında yeni bir Reel üretir.\n  <i>(Örn: <code>/reel 2026'da Yazılımcıların Yerini Alan Ajanlar</code>)</i>\n• <code>/reel</code> ➔ Hafızadaki nişe ve trendlere göre otomatik yeni bir konu seçip üretir.\n• <code>/context</code> veya <code>/profile</code> ➔ Aktif kanal hafızasını ve video üretim kurallarını gösterir.\n• <code>/set_context &lt;talimatlar&gt;</code> ➔ Kanal hafızasını günceller (Niş, ses tonu, kurallar).\n• <code>/topics</code> ➔ Üretilen son konuları ve geçmişi listeler.\n• <code>/reset_context</code> ➔ Hafızayı varsayılan şablona sıfırlar.\n\n🚀 Şimdi <code>/context</code> yazarak mevcut hafızayı görebilir veya <code>/reel</code> ile hemen video üretebilirsiniz!`;

  return [{
    json: {
      actionType: 'info',
      isInfo: true,
      chatId,
      responseText: welcomeText
    }
  }];
}

// --- Command: /context or /profile ---
if (text === '/context' || text === '/profile') {
  const p = staticData.channel_profile;
  const contextText = `🧠 <b>AI REEL FACTORY: KANAL HAFIZASI & AYARLARI</b>\n━━━━━━━━━━━━━━━━━━━━━━\n🎯 <b>Niş / Alan:</b> ${p.niche}\n👥 <b>Hedef Kitle:</b> ${p.target_audience}\n🗣️ <b>Ses Tonu:</b> ${p.tone_of_voice}\n🌐 <b>Dil:</b> ${p.language}\n🎨 <b>Görsel Tema:</b> ${p.visual_aesthetic}\n📌 <b>Özel Talimatlar:</b>\n<i>${p.custom_instructions}</i>\n━━━━━━━━━━━━━━━━━━━━━━\n⏱️ <i>Son Güncelleme: ${new Date(p.last_updated).toLocaleString('tr-TR')}</i>\n\n💡 <b>Hafızayı Güncellemek İçin:</b>\n<code>/set_context Niş: Yapay Zeka Araçları. Ton: Samimi, enerjik. Dil: Türkçe. Talimat: Kodlama bilmeyenler için pratik AI araçlarına odaklan.</code>`;

  return [{
    json: {
      actionType: 'info',
      isInfo: true,
      chatId,
      responseText: contextText
    }
  }];
}

// --- Command: /set_context <new instructions> ---
if (text.startsWith('/set_context')) {
  const newInstructions = text.replace(/^\/set_context/i, '').trim();
  if (!newInstructions) {
    return [{
      json: {
        actionType: 'info',
        isInfo: true,
        chatId,
        responseText: '⚠️ Lütfen hafızaya eklenecek talimatları belirtin.\nÖrnek: <code>/set_context Niş: Mobil Uygulama Geliştirme. Ton: İlham verici.</code>'
      }
    }];
  }

  // Update memory
  staticData.channel_profile.custom_instructions = newInstructions;
  staticData.channel_profile.last_updated = new Date().toISOString();

  // Parse key-value pairs if provided
  const nicheMatch = newInstructions.match(/Niş:\s*([^.]+)/i);
  if (nicheMatch) staticData.channel_profile.niche = nicheMatch[1].trim();

  const toneMatch = newInstructions.match(/Ton:\s*([^.]+)/i);
  if (toneMatch) staticData.channel_profile.tone_of_voice = toneMatch[1].trim();

  const langMatch = newInstructions.match(/Dil:\s*([^.]+)/i);
  if (langMatch) staticData.channel_profile.language = langMatch[1].trim();

  const confirmText = `✅ <b>KANAL HAFIZASI BAŞARIYLA GÜNCELLENDİ!</b>\n━━━━━━━━━━━━━━━━━━━━━━\nYeni bağlam kaydedildi. Bundan sonra üretilecek tüm videolar, kancalar ve görseller bu yönergelere göre şekillendirilecektir.\n\n📝 <b>Aktif Talimatlar:</b>\n<i>${newInstructions}</i>\n\n🎯 <b>Güncel Niş:</b> ${staticData.channel_profile.niche}\n🗣️ <b>Ses Tonu:</b> ${staticData.channel_profile.tone_of_voice}\n🌐 <b>Dil:</b> ${staticData.channel_profile.language}`;

  return [{
    json: {
      actionType: 'info',
      isInfo: true,
      chatId,
      responseText: confirmText
    }
  }];
}

// --- Command: /topics ---
if (text === '/topics') {
  const topicsList = (staticData.recent_topics || []).map((t, i) => `${i + 1}. <i>${t}</i>`).join('\n');
  const topicsText = `📚 <b>SON ÜRETİLEN REEL KONULARI GEÇMİŞİ</b>\n━━━━━━━━━━━━━━━━━━━━━━\n${topicsList || 'Henüz kayıtlı konu yok.'}\n━━━━━━━━━━━━━━━━━━━━━━\n💡 <i>Her yeni video üretildiğinde fabrika bu geçmişi inceler ve kendini tekrar etmez!</i>`;

  return [{
    json: {
      actionType: 'info',
      isInfo: true,
      chatId,
      responseText: topicsText
    }
  }];
}

// --- Command: /reset_context ---
if (text === '/reset_context') {
  staticData.channel_profile = defaultProfile;
  staticData.recent_topics = [
    "Why Multi-Agent AI Swarms Replace Prompts in 2026",
    "Autonomous AI Swarms in 2026",
    "AI Code Generation vs Multi-Agent Orchestration"
  ];
  return [{
    json: {
      actionType: 'info',
      isInfo: true,
      chatId,
      responseText: '🔄 <b>Kanal hafızası varsayılan ayarlara sıfırlandı.</b>'
    }
  }];
}

// --- Command: /reel <topic> or Scheduled / Generic Generation ---
let userTopic = '';
if (text) {
  userTopic = text.replace(/^\/reel/i, '').trim();
} else if (body.topic) {
  userTopic = body.topic.trim();
}

// Dynamic Pool of Backup Topics if user didn't specify one
const topicPool = [
  "Why Multi-Agent AI Swarms Replace Prompts in 2026",
  "DeepSeek R1 Architecture: Why Open Source Won the AI Race",
  "The 3 Software Engineering Skills That AI Cannot Replace",
  "Autonomous Coding Agents: How to Build 10x Faster with Swarms",
  "Zero-Click Workflows: How AI Runs Complete Businesses in 2026",
  "Local LLMs on Apple Silicon: Run 70B Models Offline in Seconds"
];

let finalTopic = userTopic;
if (!finalTopic) {
  // Pick a topic from topicPool that is not recently used
  const available = topicPool.filter(t => !(staticData.recent_topics || []).includes(t));
  finalTopic = available.length > 0 ? available[Math.floor(Math.random() * available.length)] : topicPool[Math.floor(Math.random() * topicPool.length)];
}

// Record into memory history
if (!staticData.recent_topics) staticData.recent_topics = [];
staticData.recent_topics.unshift(finalTopic);
if (staticData.recent_topics.length > 10) staticData.recent_topics.pop();

// Select best matching video from library based on topic keywords
let selectedVideoUrl = 'https://n8n-advanced.codewaft.com/media/cyber_agent.mp4';
const lowerTopic = finalTopic.toLowerCase();
for (const entry of (staticData.video_library || [])) {
  if (entry.keywords.some(kw => lowerTopic.includes(kw))) {
    selectedVideoUrl = entry.url;
    break;
  }
}

return [{
  json: {
    actionType: 'generate',
    isInfo: false,
    isStart: false,
    isCallback: false,
    topic: finalTopic,
    videoLibraryUrl: selectedVideoUrl,
    channelProfile: staticData.channel_profile,
    chatId,
    jobId: 'job_' + Date.now(),
    startedAt: new Date().toISOString()
  }
}];

