// Prepares multi-channel social distribution payload for Instagram Reels and YouTube Shorts
const item = $('Code - Normalize Input').item.json;

// Instagram Graph API credentials (Active & Verified)
const igToken = 'YOUR_INSTAGRAM_GRAPH_API_TOKEN';
const igAccountId = '17841480124544403';
const igUsername = 'developmentserhat';
const hasInstagram = Boolean(igToken && igAccountId);

// YouTube Shorts API (Multi-channel readiness)
let ytToken = '';
try {
  ytToken = $env.YOUTUBE_ACCESS_TOKEN || '';
} catch (e) {
  ytToken = '';
}
const hasYouTube = Boolean(ytToken);

return [{
  json: {
    ...item,
    publishPlan: {
      instagram: {
        enabled: hasInstagram,
        accountId: igAccountId,
        username: igUsername,
        token: igToken
      },
      youtube: {
        enabled: hasYouTube,
        token: ytToken,
        status: hasYouTube ? 'ready' : 'not_connected',
        message: hasYouTube ? 'Ready for YouTube Shorts Upload' : 'YouTube hesabı henüz bağlanmadı (İleride eklenebilir)'
      }
    }
  }
}];

// Consolidates multi-channel social posting results and formats Telegram report
const prep = $('Code - Prepare Multi-Channel Publish').item.json;
const igContainer = $('Instagram - Create Reel Container').item.json;
const igPublish = $input.first().json;

let igStatusText = '';
if (igPublish && igPublish.id) {
  igStatusText = `✅ <b>Instagram Reels:</b> Başarıyla Yayınlandı! (Medya ID: <code>${igPublish.id}</code>)\n👤 <b>Hesap:</b> @${prep.publishPlan.instagram.username}\n🔗 <b>Instagram Akışında Yayında!</b>`;
} else if (igPublish && igPublish.error) {
  const errMsg = igPublish.error.message || JSON.stringify(igPublish.error);
  igStatusText = `❌ <b>Instagram Yayınlama Hatası:</b>\n<code>${errMsg}</code>`;
} else if (igContainer && igContainer.error) {
  const errMsg = igContainer.error.message || JSON.stringify(igContainer.error);
  igStatusText = `❌ <b>Instagram Container Hatası:</b>\n<code>${errMsg}</code>`;
} else if (igContainer && igContainer.id) {
  igStatusText = `⚠️ <b>Instagram Reels:</b> Container oluşturuldu (<code>${igContainer.id}</code>) ancak yayınlanamadı.`;
} else {
  igStatusText = `⚠️ <b>Instagram Reels:</b> İşlem tamamlanamadı.`;
}

let ytStatusText = '';
if (prep.publishPlan.youtube && prep.publishPlan.youtube.enabled) {
  ytStatusText = `✅ <b>YouTube Shorts:</b> Yayında!`;
} else {
  ytStatusText = `⚠️ <b>YouTube Shorts:</b> Henüz bağlı değil (İleride eklenebilir)`;
}

let report = `🚀 <b>SOSYAL MEDYA PAYLAŞIM RAPORU</b>\n`;
report += `━━━━━━━━━━━━━━━━━━━━━━\n`;
report += `${igStatusText}\n\n`;
report += `${ytStatusText}\n`;
report += `━━━━━━━━━━━━━━━━━━━━━━\n`;
report += `📌 <b>Konu:</b> ${prep.topic}\n`;
report += `🎥 <b>Video:</b> <a href="${prep.videoUrl}">Videoyu Görüntüle / İndir ↗</a>\n\n`;
report += `📝 <b>Yayınlanan Açıklama:</b>\n<i>${prep.caption}</i>`;

return [{
  json: {
    chatId: prep.chatId,
    reportHtml: report
  }
}];

