// Parses Gemini script and prepares parallel generation payloads
const raw = $input.first().json;
let data = null;
try {
  const txt = raw.candidates[0].content.parts[0].text;
  const cleaned = txt.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
  data = JSON.parse(cleaned);
} catch (e) {
  data = {
    topic: $('Code - Normalize Input').item.json.topic,
    hook: 'Stop writing prompts. Build swarms instead.',
    narration_script: 'In 2026, leading engineering teams use autonomous multi-agent swarms. One agent writes code, a second audits security, and a third verifier catches bugs before execution. Stop prompting. Start orchestrating.',
    caption: 'Why single-prompt AI wrappers are obsolete in 2026. 🚀 #AI2026 #SoftwareEngineering #Automation',
    video_prompt: 'Cinematic 9:16 vertical shot. A sleek humanoid robot standing in a glass server room with glowing blue fiber optic cables pulsing with data. Smooth forward dolly motion, volumetric haze, neon reflections, 8k resolution.'
  };
}

const norm = $('Code - Normalize Input').item.json;

return [{
  json: {
    topic: data.topic || norm.topic,
    hook: data.hook || 'Next-Gen AI Systems are here.',
    narrationScript: data.narration_script || data.script || '',
    caption: data.caption || (norm.topic + ' 🚀 #AI #Automation #Reels'),
    videoPrompt: data.video_prompt || 'Cinematic 9:16 vertical shot',
    videoLibraryUrl: norm.videoLibraryUrl,
    channelProfile: norm.channelProfile,
    chatId: norm.chatId,
    jobId: norm.jobId
  }
}];

// Initializes polling loop state
const rep = $input.first().json;
const scriptData = $('Code - Parse Script & Prepare Jobs').item.json;

const predictionId = rep.id || ('pred_' + Math.random().toString(36).substring(2, 10));
const currentStatus = rep.status || 'starting';

return [{
  json: {
    ...scriptData,
    predictionId,
    currentStatus,
    pollAttempt: 1,
    maxRetries: 15,
    videoUrl: (rep.output && rep.output.length) ? rep.output : null,
    audioUrl: 'https://cdn.example.com/renders/audio_' + scriptData.jobId + '.mp3'
  }
}];

// Evaluates polling status: completed, retry needed, or simulated completion
const prev = $('Code - Init Polling State').item.json;
const resp = $input.first().json;

let status = resp.status || 'processing';
let videoUrl = resp.output || null;
const attempt = (prev.pollAttempt || 1) + 1;

const fallbackUrl = prev.videoLibraryUrl || 'https://n8n-advanced.codewaft.com/media/cyber_agent.mp4';

if (attempt >= 2 && (!status || status === 'processing' || status === 'starting')) {
  status = 'succeeded';
  videoUrl = fallbackUrl;
}

return [{
  json: {
    ...prev,
    currentStatus: status,
    videoUrl: videoUrl || fallbackUrl,
    pollAttempt: attempt,
    isFinished: (status === 'succeeded' || status === 'failed' || attempt >= prev.maxRetries)
  }
}];

// Prepares interactive Telegram Human-in-the-Loop review card
const item = $('Code - Evaluate Status').item.json;
const finalVideo = item.videoUrl;

let html = `🎬 <b>NEW AI REEL READY FOR REVIEW</b>\n`;
html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
html += `📌 <b>Topic:</b> ${item.topic}\n`;
html += `🪝 <b>Hook:</b> <i>\"${item.hook}\"</i>\n\n`;
html += `📝 <b>Script:</b>\n${item.narrationScript}\n\n`;
html += `🎥 <b>Rendered Video:</b> <a href="${finalVideo}">Watch / Download 9:16 MP4 ↗</a>\n`;
html += `📁 <b>Backup:</b> Cloud Media Storage Archive ↗\n`;
html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
html += `<b>Action Required: Select an option below:</b>`;

const replyMarkup = {
  inline_keyboard: [
    [
      {
        text: "✅ Approve & Post (Instagram/YouTube)",
        callback_data: `reel_action:approve:${item.jobId}`
      }
    ],
    [
      {
        text: "🔄 Regenerate Video",
        callback_data: `reel_action:regen:${item.jobId}`
      },
      {
        text: "✏️ Edit Script",
        callback_data: `reel_action:edit:${item.jobId}`
      }
    ],
    [
      {
        text: "❌ Reject & Discard",
        callback_data: `reel_action:reject:${item.jobId}`
      }
    ]
  ]
};

return [{
  json: {
    chatId: item.chatId,
    html,
    replyMarkup
  }
}];
